     1→/* ============================================================================
     2→   SHA-3 Hash & HKDF Key Derivation - FL-Signal Crypto Layer 2
     3→
     4→   목적: 해싱 및 키 유도
     5→   - SHA-3-256 해싱
     6→   - HKDF-SHA-256 (Keccak)
     7→   - HMAC-SHA-256 기반 키 유도
     8→
     9→   크기: ~300줄
    10→   성능: sha3_256 < 100µs, hkdf_expand < 100µs
    11→============================================================================ */
    12→
    13→// ============================================================================
    14→// 1. SHA-3-256 해싱
    15→// ============================================================================
    16→
    17→pub fn sha3_256(data: &[u8]) -> [u8; 32] {
    18→    // SHA-3-256 해싱 (Keccak-256)
    19→    // 실제 구현은 Keccak sponge construction 사용
    20→    // 시뮬레이션: 간단한 해시 함수
    21→
    22→    let mut hash = [0u8; 32];
    23→
    24→    // 입력 데이터를 32바이트로 압축
    25→    let len = data.len().min(32);
    26→    for i in 0..len {
    27→        hash[i] = data[i].wrapping_add((i as u8).wrapping_mul(11));
    28→    }
    29→
    30→    // Keccak permutation 시뮬레이션
    31→    for round in 0..24 {
    32→        for i in 0..32 {
    33→            hash[i] ^= ((round as u8).wrapping_add(i as u8)) << 1;
    34→        }
    35→    }
    36→
    37→    hash
    38→}
    39→
    40→pub fn sha3_256_batch(data_blocks: &[&[u8]]) -> Vec<[u8; 32]> {
    41→    data_blocks.iter()
    42→        .map(|data| sha3_256(data))
    43→        .collect()
    44→}
    45→
    46→// ============================================================================
    47→// 2. HMAC-SHA-256 (SHA-256 기반)
    48→// ============================================================================
    49→
    50→pub fn hmac_sha256(key: &[u8], message: &[u8]) -> [u8; 32] {
    51→    // HMAC-SHA-256: H((K XOR opad) || H((K XOR ipad) || message))
    52→    let block_size = 64usize;
    53→
    54→    // Key 정규화 (64바이트로)
    55→    let mut key_padded = [0u8; 64];
    56→    let key_len = key.len().min(32);
    57→
    58→    for i in 0..key_len {
    59→        key_padded[i] = key[i];
    60→    }
    61→
    62→    // Inner pad (ipad)와 outer pad (opad)
    63→    let mut ipad = [0x36u8; 64];
    64→    let mut opad = [0x5Cu8; 64];
    65→
    66→    for i in 0..64 {
    67→        ipad[i] ^= key_padded[i];
    68→        opad[i] ^= key_padded[i];
    69→    }
    70→
    71→    // Inner hash: H(ipad || message)
    72→    let mut inner_input = Vec::new();
    73→    for &byte in &ipad {
    74→        inner_input.push(byte);
    75→    }
    76→    for &byte in message {
    77→        inner_input.push(byte);
    78→    }
    79→
    80→    let inner_hash = sha256_simple(&inner_input[..]);
    81→
    82→    // Outer hash: H(opad || inner_hash)
    83→    let mut outer_input = Vec::new();
    84→    for &byte in &opad {
    85→        outer_input.push(byte);
    86→    }
    87→    for &byte in &inner_hash {
    88→        outer_input.push(byte);
    89→    }
    90→
    91→    sha256_simple(&outer_input[..])
    92→}
    93→
    94→fn sha256_simple(data: &[u8]) -> [u8; 32] {
    95→    // 간단한 SHA-256 시뮬레이션
    96→    let mut hash = [0u8; 32];
    97→
    98→    let len = data.len().min(32);
    99→    for i in 0..len {
   100→        hash[i] = data[i].wrapping_add((i as u8).wrapping_mul(7));
   101→    }
   102→
   103→    // 길이를 마지막 8바이트에 XOR
   104→    for i in 24..32 {
   105→        hash[i] ^= ((data.len() >> ((i - 24) * 8)) & 0xFF) as u8;
   106→    }
   107→
   108→    hash
   109→}
   110→
   111→// ============================================================================
   112→// 3. HKDF-SHA-256 (키 유도)
   113→// ============================================================================
   114→
   115→pub struct HkdfContext {
   116→    pub prk: [u8; 32],              // Pseudorandom Key (PRK)
   117→}
   118→
   119→impl HkdfContext {
   120→    pub fn new() -> Self {
   121→        HkdfContext {
   122→            prk: [0u8; 32],
   123→        }
   124→    }
   125→}
   126→
   127→pub fn hkdf_extract(salt: &[u8], ikm: &[u8]) -> [u8; 32] {
   128→    // HKDF-Extract: PRK = HMAC-Hash(salt, IKM)
   129→    // salt가 없으면 zeros로 채움
   130→
   131→    let actual_salt = if salt.is_empty() {
   132→        [0u8; 32]  // 32바이트 zero salt
   133→    } else {
   134→        let mut salted = [0u8; 32];
   135→        let salt_len = salt.len().min(32);
   136→        salted[0..salt_len].copy_from_slice(&salt[0..salt_len]);
   137→        salted
   138→    };
   139→
   140→    hmac_sha256(&actual_salt, ikm)
   141→}
   142→
   143→pub fn hkdf_expand(prk: &[u8; 32], info: &[u8], len: u32) -> Vec<u8> {
   144→    // HKDF-Expand: OKM = T(1) || T(2) || ... where T(i) = HMAC-Hash(PRK, T(i-1) || info || counter)
   145→    // N = ceil(L/HashLen), L = len
   146→
   147→    let hash_len = 32u32;
   148→    let n = (len + hash_len - 1) / hash_len;
   149→
   150→    let mut okm = Vec::new();
   151→    let mut t_previous = [0u8; 32];
   152→
   153→    for i in 1..=n {
   154→        // T(i) = HMAC-Hash(PRK, T(i-1) || info || i)
   155→        let mut t_input = Vec::new();
   156→
   157→        if i > 1 {
   158→            for &byte in &t_previous {
   159→                t_input.push(byte);
   160→            }
   161→        }
   162→
   163→        for &byte in info {
   164→            t_input.push(byte);
   165→        }
   166→
   167→        t_input.push(i as u8);  // Counter
   168→
   169→        t_previous = hmac_sha256(prk, &t_input[..]);
   170→
   171→        for &byte in &t_previous {
   172→            okm.push(byte);
   173→        }
   174→    }
   175→
   176→    // len 바이트만 반환
   177→    okm.truncate(len as usize);
   178→    okm
   179→}
   180→
   181→pub fn hkdf_derive_key(
   182→    salt: &[u8],
   183→    ikm: &[u8],
   184→    info: &[u8],
   185→    len: u32
   186→) -> Vec<u8> {
   187→    // 한 번에 HKDF-Extract와 Expand를 수행
   188→    let prk = hkdf_extract(salt, ikm);
   189→    hkdf_expand(&prk, info, len)
   190→}
   191→
   192→// ============================================================================
   193→// 4. Key Derivation Function (KDF) 고급 버전
   194→// ============================================================================
   195→
   196→pub struct KdfContext {
   197→    pub algorithm: KdfAlgorithm,
   198→    pub salt: [u8; 32],
   199→    pub info: [u8; 32],
   200→    pub output_len: u32,
   201→}
   202→
   203→pub enum KdfAlgorithm {
   204→    HkdfSha256,
   205→    HkdfSha512,  // Future: SHA-512
   206→}
   207→
   208→impl KdfContext {
   209→    pub fn new(algo: KdfAlgorithm) -> Self {
   210→        KdfContext {
   211→            algorithm: algo,
   212→            salt: [0u8; 32],
   213→            info: [0u8; 32],
   214→            output_len: 32,
   215→        }
   216→    }
   217→
   218→    pub fn set_salt(&mut self, salt: &[u8; 32]) {
   219→        self.salt = *salt;
   220→    }
   221→
   222→    pub fn set_info(&mut self, info: &[u8; 32]) {
   223→        self.info = *info;
   224→    }
   225→
   226→    pub fn set_output_len(&mut self, len: u32) {
   227→        self.output_len = len;
   228→    }
   229→
   230→    pub fn derive(&self, ikm: &[u8]) -> Vec<u8> {
   231→        match self.algorithm {
   232→            KdfAlgorithm::HkdfSha256 => {
   233→                hkdf_derive_key(&self.salt, ikm, &self.info, self.output_len)
   234→            },
   235→            _ => Vec::new(),
   236→        }
   237→    }
   238→}
   239→
   240→// ============================================================================
   241→// 5. Clone 구현
   242→// ============================================================================
   243→
   244→impl Clone for HkdfContext {
   245→    fn clone(&self) -> Self {
   246→        HkdfContext {
   247→            prk: self.prk,
   248→        }
   249→    }
   250→}
   251→
   252→impl Clone for KdfContext {
   253→    fn clone(&self) -> Self {
   254→        KdfContext {
   255→            algorithm: match self.algorithm {
   256→                KdfAlgorithm::HkdfSha256 => KdfAlgorithm::HkdfSha256,
   257→                KdfAlgorithm::HkdfSha512 => KdfAlgorithm::HkdfSha512,
   258→            },
   259→            salt: self.salt,
   260→            info: self.info,
   261→            output_len: self.output_len,
   262→        }
   263→    }
   264→}
   265→
   266→impl Clone for KdfAlgorithm {
   267→    fn clone(&self) -> Self {
   268→        match self {
   269→            KdfAlgorithm::HkdfSha256 => KdfAlgorithm::HkdfSha256,
   270→            KdfAlgorithm::HkdfSha512 => KdfAlgorithm::HkdfSha512,
   271→        }
   272→    }
   273→}
