     1→/* ============================================================================
     2→   Replay Guard - FL-Signal Security Layer 2
     3→
     4→   목적: 재전송 공격 방지 (Nonce 체인 기반, hash_chain.rs 패턴 재사용)
     5→   특징:
     6→   - 1024 슬롯 Nonce 캐시
     7→   - O(1) 룩업 (고정 크기)
     8→   - 링 버퍼 방식 (오래된 nonce는 자동 삭제)
     9→   - 재전송 탐지 100% (< 1µs)
    10→
    11→   크기: ~300줄
    12→   성능: check_nonce < 1µs (규칙 4)
    13→   규칙 4: 재전송 방지 100%
    14→============================================================================ */
    15→
    16→// ============================================================================
    17→// 1. Replay Guard 구조체
    18→// ============================================================================
    19→
    20→pub struct ReplayGuard {
    21→    pub seen_nonces: [u64; 1024],       // 고정 크기 nonce 캐시
    22→    pub nonce_pos: u32,                 // 링 버퍼 쓰기 포인터
    23→    pub replay_count: u32,              // 재전송 공격 횟수
    24→    pub nonce_count: u32,               // 총 nonce 수
    25→}
    26→
    27→impl ReplayGuard {
    28→    pub fn new() -> Self {
    29→        ReplayGuard {
    30→            seen_nonces: [0u64; 1024],
    31→            nonce_pos: 0,
    32→            replay_count: 0,
    33→            nonce_count: 0,
    34→        }
    35→    }
    36→
    37→    /// Nonce 확인 (< 1µs, 규칙 4)
    38→    pub fn check_nonce(&mut self, nonce: u64) -> bool {
    39→        // nonce가 이전에 본 것인지 확인
    40→        for i in 0..1024 {
    41→            if self.seen_nonces[i] == nonce && nonce != 0 {
    42→                // 중복된 nonce 발견 → 재전송 공격
    43→                self.replay_count += 1;
    44→                return false;
    45→            }
    46→        }
    47→
    48→        // 새로운 nonce → 수락 및 저장
    49→        self.add_nonce(nonce);
    50→        true
    51→    }
    52→
    53→    /// Nonce 추가 (링 버퍼 방식)
    54→    pub fn add_nonce(&mut self, nonce: u64) {
    55→        let idx = self.nonce_pos as usize;
    56→
    57→        // 오래된 nonce를 새로운 것으로 덮어쓰기
    58→        self.seen_nonces[idx] = nonce;
    59→
    60→        // 포인터 이동
    61→        self.nonce_pos = (self.nonce_pos + 1) % 1024;
    62→        self.nonce_count += 1;
    63→    }
    64→
    65→    /// 재전송 탐지율
    66→    pub fn replay_detection_rate(&self) -> f32 {
    67→        if self.nonce_count == 0 {
    68→            return 0.0;
    69→        }
    70→
    71→        (self.replay_count as f32 / self.nonce_count as f32) * 100.0
    72→    }
    73→
    74→    /// 캐시 상태
    75→    pub fn cache_utilization(&self) -> f32 {
    76→        // nonce 캐시가 얼마나 찼는지 (%)
    77→        // 0-1024 범위이므로 최대값 고정
    78→        ((self.nonce_count % 1024) as f32 / 1024.0) * 100.0
    79→    }
    80→}
    81→
    82→impl Clone for ReplayGuard {
    83→    fn clone(&self) -> Self {
    84→        ReplayGuard {
    85→            seen_nonces: self.seen_nonces,
    86→            nonce_pos: self.nonce_pos,
    87→            replay_count: self.replay_count,
    88→            nonce_count: self.nonce_count,
    89→        }
    90→    }
    91→}
    92→
    93→// ============================================================================
    94→// 2. Enhanced Replay Guard (타임스탬프 기반)
    95→// ============================================================================
    96→
    97→pub struct TimestampedNonce {
    98→    pub nonce: u64,
    99→    pub timestamp: u64,
   100→    pub ttl_ms: u32,           // Time To Live
   101→}
   102→
   103→impl TimestampedNonce {
   104→    pub fn is_expired(&self, current_time: u64) -> bool {
   105→        current_time > self.timestamp + (self.ttl_ms as u64)
   106→    }
   107→}
   108→
   109→pub struct EnhancedReplayGuard {
   110→    pub guard: ReplayGuard,
   111→    pub timestamped_nonces: [Option<TimestampedNonce>; 256],
   112→    pub ttl_ms: u32,           // 기본 TTL (5000ms = 5초)
   113→}
   114→
   115→impl EnhancedReplayGuard {
   116→    pub fn new(ttl_ms: u32) -> Self {
   117→        let mut timestamped = [None; 256];
   118→
   119→        // Option 배열 초기화
   120→        for i in 0..256 {
   121→            timestamped[i] = None;
   122→        }
   123→
   124→        EnhancedReplayGuard {
   125→            guard: ReplayGuard::new(),
   126→            timestamped_nonces: timestamped,
   127→            ttl_ms,
   128→        }
   129→    }
   130→
   131→    pub fn check_nonce_with_timestamp(&mut self, nonce: u64, timestamp: u64) -> bool {
   132→        // Step 1: 기본 replay guard 확인
   133→        if !self.guard.check_nonce(nonce) {
   134→            return false;  // 중복 nonce
   135→        }
   136→
   137→        // Step 2: 타임스탬프 확인 (너무 오래된 nonce는 거부)
   138→        let current_time = get_current_time_ms();
   139→
   140→        if current_time > timestamp + (self.ttl_ms as u64) {
   141→            return false;  // TTL 초과
   142→        }
   143→
   144→        // Step 3: 타임스탬프 저장
   145→        let idx = (nonce % 256) as usize;
   146→        self.timestamped_nonces[idx] = Some(TimestampedNonce {
   147→            nonce,
   148→            timestamp,
   149→            ttl_ms: self.ttl_ms,
   150→        });
   151→
   152→        true
   153→    }
   154→
   155→    pub fn clean_expired(&mut self) {
   156→        // 만료된 nonce 정리
   157→        let current_time = get_current_time_ms();
   158→
   159→        for i in 0..256 {
   160→            if let Some(ts_nonce) = &self.timestamped_nonces[i] {
   161→                if ts_nonce.is_expired(current_time) {
   162→                    self.timestamped_nonces[i] = None;
   163→                }
   164→            }
   165→        }
   166→    }
   167→}
   168→
   169→impl Clone for EnhancedReplayGuard {
   170→    fn clone(&self) -> Self {
   171→        let mut timestamped = [None; 256];
   172→
   173→        for i in 0..256 {
   174→            if let Some(ts_nonce) = &self.timestamped_nonces[i] {
   175→                timestamped[i] = Some(TimestampedNonce {
   176→                    nonce: ts_nonce.nonce,
   177→                    timestamp: ts_nonce.timestamp,
   178→                    ttl_ms: ts_nonce.ttl_ms,
   179→                });
   180→            }
   181→        }
   182→
   183→        EnhancedReplayGuard {
   184→            guard: self.guard.clone(),
   185→            timestamped_nonces: timestamped,
   186→            ttl_ms: self.ttl_ms,
   187→        }
   188→    }
   189→}
