   191→// ============================================================================
   192→// 3. Nonce 생성기 (Cryptographic)
   193→// ============================================================================
   194→
   195→pub struct NonceGenerator {
   196→    pub counter: u64,
   197→}
   198→
   199→impl NonceGenerator {
   200→    pub fn new() -> Self {
   201→        NonceGenerator { counter: 0 }
   202→    }
   203→
   204→    pub fn generate_nonce(&mut self) -> u64 {
   205→        // 카운터 기반 nonce (실제로는 랜덤)
   206→        self.counter = self.counter.wrapping_add(1);
   207→
   208→        // 카운터를 해시하여 nonce 생성
   209→        hash_nonce(self.counter)
   210→    }
   211→
   212→    pub fn generate_nonce_batch(&mut self, count: u32) -> Vec<u64> {
   213→        let mut nonces = Vec::new();
   214→
   215→        for _ in 0..count {
   216→            nonces.push(self.generate_nonce());
   217→        }
   218→
   219→        nonces
   220→    }
   221→}
   222→
   223→impl Clone for NonceGenerator {
   224→    fn clone(&self) -> Self {
   225→        NonceGenerator {
   226→            counter: self.counter,
   227→        }
   228→    }
   229→}
   230→
   231→// ============================================================================
   232→// 4. 유틸리티 함수
   233→// ============================================================================
   234→
   235→fn hash_nonce(value: u64) -> u64 {
   236→    // 간단한 해시 함수 (시뮬레이션)
   237→    let mixed = value.wrapping_mul(6364136223846793005)
   238→        .wrapping_add(1442695040888963407);
   239→
   240→    mixed ^ (mixed >> 33)
   241→}
   242→
   243→fn get_current_time_ms() -> u64 {
   244→    // 시뮬레이션: 현재 시간 (ms)
   245→    static mut TIME: u64 = 0;
   246→    unsafe {
   247→        TIME = TIME.wrapping_add(1);
   248→        TIME
   249→    }
   250→}
