    15→
    16→// ============================================================================
    17→// 1. Signal Threat 분류
    18→// ============================================================================
    19→
    20→pub enum SignalThreat {
    21→    Clean = 0,           // 정상 신호
    22→    Jamming = 1,         // 재밍 (노이즈 공격)
    23→    Spoofing = 2,        // 스푸핑 (위조 신호)
    24→    Replay = 3,          // 재전송 (기록된 신호 재사용)
    25→    Unknown = 255,       // 분류 불가
    26→}
    27→
    28→impl SignalThreat {
    29→    pub fn to_u8(&self) -> u8 {
    30→        match self {
    31→            SignalThreat::Clean => 0,
    32→            SignalThreat::Jamming => 1,
    33→            SignalThreat::Spoofing => 2,
    34→            SignalThreat::Replay => 3,
    35→            SignalThreat::Unknown => 255,
    36→        }
    37→    }
    38→}
    39→
    40→impl Clone for SignalThreat {
    41→    fn clone(&self) -> Self {
    42→        match self {
    43→            SignalThreat::Clean => SignalThreat::Clean,
    44→            SignalThreat::Jamming => SignalThreat::Jamming,
    45→            SignalThreat::Spoofing => SignalThreat::Spoofing,
    46→            SignalThreat::Replay => SignalThreat::Replay,
    47→            SignalThreat::Unknown => SignalThreat::Unknown,
    48→        }
    49→    }
    50→}
