    50→// ============================================================================
    51→// 2. Signal Channel 구조체
    52→// ============================================================================
    53→
    54→pub struct SignalChannel {
    55→    pub channel_id: u64,                  // 채널 ID (unique)
    56→    pub local_key: [u8; 32],              // 로컬 공개 키
    57→    pub remote_key: [u8; 32],             // 원격 공개 키
    58→    pub session_key: [u8; 32],            // ECDH 세션 키
    59→    pub state: ChannelState,              // 채널 상태
    60→    pub message_count: u64,               // 송수신 메시지 카운트
    61→    pub bytes_sent: u64,                  // 전송 바이트
    62→    pub bytes_received: u64,              // 수신 바이트
    63→    pub created_timestamp: u64,           // 채널 생성 시간
    64→}
    65→
    66→impl SignalChannel {
    67→    pub fn new(channel_id: u64, local_key: &[u8; 32]) -> Self {
    68→        SignalChannel {
    69→            channel_id,
    70→            local_key: *local_key,
    71→            remote_key: [0u8; 32],
    72→            session_key: [0u8; 32],
    73→            state: ChannelState::Idle,
    74→            message_count: 0,
    75→            bytes_sent: 0,
    76→            bytes_received: 0,
    77→            created_timestamp: get_time_ms(),
    78→        }
    79→    }
    80→
    81→    pub fn is_active(&self) -> bool {
    82→        match self.state {
    83→            ChannelState::Active => true,
    84→            _ => false,
    85→        }
    86→    }
    87→
    88→    pub fn is_ready_for_handshake(&self) -> bool {
    89→        match self.state {
    90→            ChannelState::Idle => true,
    91→            _ => false,
    92→        }
    93→    }
    94→
    95→    pub fn get_channel_duration_ms(&self) -> u64 {
