   279→            bytes_sent: channel.bytes_sent,
   280→            bytes_received: channel.bytes_received,
   281→            throughput_mps: throughput_mps(channel),
   282→            throughput_mbps: throughput_mbps(channel),
   283→            duration_ms: channel.get_channel_duration_ms(),
